using Vitarish.Medical.Contracts.Enums;
using Vitarish.Medical.Contracts.Requests;
using Vitarish.Medical.Contracts.Responses;
using Vitarish.Medical.Contracts.Results;

namespace Vitarish.Medical.Interface.Components.Base;

public static class MedicalClientPresentationExtensions
{
    private static MedicalCommandResult ToCommandResult(MedicalResult<MedicalCommandResult> result) =>
        result.IsSuccess && result.Value is not null
            ? result.Value
            : new MedicalCommandResult(Accepted: false, UserSafeMessage: result.Failure?.Message);

    public static async Task<T> ValueOrDefault<T>(this Task<MedicalResult<T>> task, T fallback)
    {
        MedicalResult<T> result = await task.ConfigureAwait(false);
        return result.IsSuccess && result.Value is not null ? result.Value : fallback;
    }

    public static async Task<CodeSystem?> GetCodeSystemAsync(this IMedicalClient client, Guid id) =>
        await client.GetCodeSystemAsync(new GetCodeSystemRequest(id), CancellationToken.None).ValueOrDefault<CodeSystem?>(null);
    public static async Task<IReadOnlyList<CodeSystem>> ListCodeSystemsAsync(this IMedicalClient client, bool activeOnly = true) =>
        await client.ListCodeSystemsAsync(new ListCodeSystemsRequest(activeOnly), CancellationToken.None).ValueOrDefault<IReadOnlyList<CodeSystem>>([]);
    public static async Task<IReadOnlyList<CodeSystemRelease>> ListReleasesAsync(this IMedicalClient client, Guid codeSystemId, bool activeOnly = true) =>
        await client.ListCodeSystemReleasesAsync(new ListCodeSystemReleasesRequest(codeSystemId, activeOnly), CancellationToken.None).ValueOrDefault<IReadOnlyList<CodeSystemRelease>>([]);
    public static async Task<IReadOnlyList<MedicalCode>> SearchMedicalCodesAsync(this IMedicalClient client, string systemKey, string text) =>
        await client.SearchMedicalCodesAsync(new SearchMedicalCodesRequest(systemKey, text), CancellationToken.None).ValueOrDefault<IReadOnlyList<MedicalCode>>([]);
    public static async Task<IReadOnlyList<MedicalCode>> SearchMedicalCodesAsync(this IMedicalClient client, string systemKey, string text, int limit) =>
        await client.SearchMedicalCodesAsync(new SearchMedicalCodesRequest(systemKey, text, Limit: limit), CancellationToken.None).ValueOrDefault<IReadOnlyList<MedicalCode>>([]);
    public static async Task<MedicalCode?> ResolveMedicalCodeAsync(this IMedicalClient client, string systemKey, string code) =>
        (await client.ResolveMedicalCodeAsync(new ResolveMedicalCodeRequest(systemKey, code), CancellationToken.None).ValueOrDefault<MedicalCodeResponse?>(null)) is { } value
            ? new MedicalCode { Id = value.Id, Code = value.Code, DisplayName = value.DisplayName, Status = value.Status }
            : null;
    public static async Task<IReadOnlyList<Drug>> SearchDrugsAsync(this IMedicalClient client, string text) =>
        await client.SearchDrugsAsync(new SearchDrugsRequest(text), CancellationToken.None).ValueOrDefault<IReadOnlyList<Drug>>([]);
